<title>JTCVS Article</title>
<style>
    body {
        margin: 0;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background-color: #f0f0f0;
        display: flex;
        justify-content: center;
    }
    .app-container {
        width: 100%;
        max-width: 414px;
        background-color: #fff;
        box-shadow: 0 0 20px rgba(0,0,0,0.1);
        min-height: 100vh;
    }

    /* Header */
    .header {
        background-color: #003380;
        color: white;
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 15px 20px;
    }
    .logo-group {
        display: flex;
        align-items: center;
    }
    .logo-icon {
        width: 18px;
        height: 22px;
        border: 1px solid white;
        border-radius: 0 0 10px 10px;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 7px;
        margin-right: 8px;
        font-family: sans-serif;
    }
    .logo-text {
        font-family: "Times New Roman", Times, serif;
        font-size: 26px;
        letter-spacing: 1px;
    }
    .login-btn {
        font-size: 16px;
        cursor: pointer;
    }

    /* Search */
    .search-section {
        display: flex;
        align-items: center;
        padding: 12px 20px;
        border-bottom: 1px solid #e0e0e0;
    }
    .menu-btn {
        margin-right: 15px;
        display: flex;
        align-items: center;
        cursor: pointer;
    }
    .search-box {
        display: flex;
        flex-grow: 1;
        border: 1px solid #ccc;
        border-radius: 3px;
        overflow: hidden;
    }
    .search-input {
        flex-grow: 1;
        border: none;
        padding: 10px 12px;
        font-size: 15px;
        outline: none;
    }
    .search-submit {
        background-color: white;
        border: none;
        border-left: 1px solid #ccc;
        padding: 0 12px;
        display: flex;
        align-items: center;
        cursor: pointer;
    }

    /* Hero */
    .hero-section {
        background: linear-gradient(145deg, #003380 0%, #1a4c9a 40%, #2a60b5 100%);
        color: white;
        padding: 25px 20px;
        position: relative;
    }
    .meta-info {
        font-size: 11px;
        text-transform: uppercase;
        margin-bottom: 18px;
        line-height: 1.5;
        letter-spacing: 0.5px;
        color: rgba(255,255,255,0.9);
    }
    .meta-info strong {
        font-weight: 600;
        color: white;
    }
    .title {
        font-size: 22px;
        font-weight: 400;
        margin-bottom: 25px;
        line-height: 1.3;
    }
    .authors-list {
        font-size: 14px;
        line-height: 2.2;
        margin-bottom: 20px;
    }
    .author {
        display: inline-block;
    }
    .line-white {
        border-bottom: 1px solid white;
        padding-bottom: 2px;
    }
    .line-red {
        border-bottom: 2px solid #e74c3c;
        padding-bottom: 2px;
    }
    .dot-separator {
        margin: 0 5px;
    }
    .author-actions {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        margin-left: 6px;
        vertical-align: middle;
    }
    .action-icon {
        border: 1px solid white;
        border-radius: 2px;
        padding: 2px;
        display: flex;
    }

    .pub-details {
        font-size: 13px;
        margin-bottom: 12px;
    }
    .text-orange {
        color: #f39c12;
    }
    .doi-link {
        font-size: 13px;
        margin-bottom: 35px;
    }
    .doi-link a {
        color: white;
        text-decoration: none;
        border-bottom: 1px solid rgba(255,255,255,0.5);
    }

    .metrics-badge {
        position: absolute;
        bottom: 20px;
        right: 20px;
        display: flex;
        align-items: center;
        font-size: 15px;
    }
    .metrics-icon {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 2px;
        margin-right: 8px;
    }
    .m-dot {
        width: 5px;
        height: 5px;
        border-radius: 50%;
    }
    .bg-pink { background-color: #e84c8f; }
    .bg-orange { background-color: #f39c12; }
    .bg-purple { background-color: #9b59b6; }
    .bg-blue { background-color: #3498db; }

    /* Content */
    .main-content {
        padding: 25px 20px;
        background-color: white;
    }
    .divider {
        border-top: 1px solid #e0e0e0;
        margin-bottom: 25px;
    }

    .media-layout {
        position: relative;
        padding-bottom: 40px;
    }
    .media-placeholder {
        width: 240px;
        height: 220px;
        background-color: #000;
        display: flex;
        justify-content: center;
        align-items: center;
        color: white;
        font-size: 12px;
        text-align: center;
        padding: 10px;
        box-sizing: border-box;
    }

    .primary-btn {
        position: absolute;
        bottom: 15px;
        left: 0;
        background-color: #0044aa;
        color: white;
        width: 50px;
        height: 50px;
        border: none;
        display: flex;
        justify-content: center;
        align-items: center;
        cursor: pointer;
    }

    .secondary-btns {
        position: absolute;
        bottom: 0;
        right: 0;
        display: flex;
        gap: 5px;
    }
    .sec-btn {
        background-color: #999;
        color: white;
        width: 45px;
        height: 45px;
        border: none;
        display: flex;
        justify-content: center;
        align-items: center;
        cursor: pointer;
    }

</style>
</head>
